  "「市役所の近くの事務所で働いていました。」佐々木さんは海のほうを見つめたまま話した。「揺れは、三分以上続きました。大津波警報が出て、わたしは裏の山へ走りました。でも、母は『ここまでは来ない。前のチリ地震の津波のときも大丈夫だった』と言って、家に残ったんです。」風が、植えたばかりの若い松を揺らした。「母は、見つかりませんでした。」": "シヤクショ ノ チカク ノ ジムショ デ ハタライテ イマシタ ササキサン ハ ウミ ノ ホウ ヲ ミツメタ ママ ハナシタ ユレ ハ サンプン イジョウ ツヅキマシタ ダイツナミ ケイホウ ガ デテ ワタシ ハ ウラ ノ ヤマ ヘ ハシリマシタ デモ ハハ ハ ココ マデ ハ コナイ マエ ノ チリ ジシン ノ ツナミ ノ トキ モ ダイジョウブダッタ ト イッテ イエ ニ ノコッタ ンデス カゼ ガ ウエタ バカリ ノ ワカイ マツ ヲ ユラシタ ハハ ハ ミツカリマセンデシタ|シヤクショ ノ チカク ノ ジムショ デ ハタライテ イマシタ ササキサン ワ ウミ ノ ホー ヲ ミツメタ ママ ハナシタ ユレ ワ サンプン イジョー ツズキマシタ ダイツナミ ケイホー ガ デテ ワタシ ワ ウラ ノ ヤマ エ ハシリマシタ デモ ハハ ワ ココ マデ ワ コナイ マエ ノ チリ ジシン ノ ツナミ ノ トキ モ ダイジョーブダッタ ト イッテ イエ ニ ノコッタ ンデス カゼ ガ ウエタ バカリ ノ ワカイ マツ ヲ ユラシタ ハハ ワ ミツカリマセンデシタ",
