  "マスターはカップをふきながら、静かに話した。「二回目の観測隊が来たとき、氷があまりに厚くて、船が基地に近づけなかったんだ。天気も悪くて、隊員を運ぶだけで精いっぱいだった。犬たちは、鎖につながれたまま置いていかれたんだよ。」少し間をおいて、マスターは続けた。「だから、二匹が走ってきたってニュースを聞いたとき、日本中の子どもが泣いたもんさ。」": "マスター ハ カップ ヲ フキナガラ シズカ ニ ハナシタ ニカイメ ノ カンソクタイ ガ キタ トキ コオリ ガ アマリニ アツクテ フネ ガ キチ ニ チカヅケナカッタ ンダ テンキ モ ワルクテ タイイン ヲ ハコブ ダケ デ セイイッパイダッタ イヌタチ ハ クサリ ニ ツナガレタ ママ オイテ イカレタ ンダ ヨ スコシ マ ヲ オイテ マスター ハ ツヅケタ ダカラ ニヒキ ガ ハシッテ キタ ッテ ニュース ヲ キイタ トキ ニホン チュウ ノ コドモ ガ ナイタ モン サ|マスター ワ カップ ヲ フキナガラ シズカ ニ ハナシタ ニカイメ ノ カンソクタイ ガ キタ トキ コーリ ガ アマリニ アツクテ フネ ガ キチ ニ チカズケナカッタ ンダ テンキ モ ワルクテ タイイン ヲ ハコブ ダケ デ セイイッパイダッタ イヌタチ ワ クサリ ニ ツナガレタ ママ オイテ イカレタ ンダ ヨ スコシ マ ヲ オイテ マスター ワ ツズケタ ダカラ ニヒキ ガ ハシッテ キタ ッテ ニュース ヲ キイタ トキ ニホン チュー ノ コドモ ガ ナイタ モン サ",
