  "一週間、リヌは毎晩、百枚の札を並べて練習した。大会の日、読み手が「む」と読んだ瞬間、手が動いた。「村雨の……」。結果は三回戦負けだったが、結衣さんが言った。「一字決まり、ほとんど取れてたよ。千年前の歌が、ちゃんと耳に入ってる。」": "イチシュウカン リヌ ハ マイバン ヒャクマイ ノ フダ ヲ ナラベテ レンシュウ シタ タイカイ ノ ヒ ヨミテ ガ ム ト ヨンダ シュンカン テ ガ ウゴイタ ムラサメ ノ ケッカ ハ サンカイセン マケダッタガ ユイサン ガ イッタ イチジ キマリ ホトンド トレ テタ ヨ センネン マエ ノ ウタ ガ チャント ミミ ニ ハイッ テル|イチシューカン リヌ ワ マイバン ヒャクマイ ノ フダ ヲ ナラベテ レンシュー シタ タイカイ ノ ヒ ヨミテ ガ ム ト ヨンダ シュンカン テ ガ ウゴイタ ムラサメ ノ ケッカ ワ サンカイセン マケダッタガ ユイサン ガ イッタ イチジ キマリ ホトンド トレ テタ ヨ センネン マエ ノ ウタ ガ チャント ミミ ニ ハイッ テル",
  "一週間後、リヌのもとにメールが届いた。「慎重に検討いたしました結果、誠に残念ながら、今回は採用を見送らせていただくことになりました。」中洲の屋台で、拓海がラーメンをおごってくれた。「最後の質問、大事やったとよ。次はきっとうまくいくけん。」リヌはスープを飲みながら、次の面接で聞くことをノートに書き始めた。": "イチシュウカンゴ リヌ ノ モト ニ メール ガ トドイタ シンチョウ ニ ケントウ イタシマシタ ケッカ マコトニ ザンネンナガラ コンカイ ハ サイヨウ ヲ ミオクラセテ イタダク コト ニ ナリマシタ ナカス ノ ヤタイ デ タクミ ガ ラーメン ヲ オゴッテ クレタ サイゴ ノ シツモン ダイジ ヤッタ ト ヨ ツギ ハ キット ウマク イク ケ ン リヌ ハ スープ ヲ ノミナガラ ツギ ノ メンセツ デ キク コト ヲ ノート ニ カキ ハジメタ|イチシューカンゴ リヌ ノ モト ニ メール ガ トドイタ シンチョー ニ ケントー イタシマシタ ケッカ マコトニ ザンネンナガラ コンカイ ワ サイヨー ヲ ミオクラセテ イタダク コト ニ ナリマシタ ナカス ノ ヤタイ デ タクミ ガ ラーメン ヲ オゴッテ クレタ サイゴ ノ シツモン ダイジ ヤッタ ト ヨ ツギ ワ キット ウマク イク ケ ン リヌ ワ スープ ヲ ノミナガラ ツギ ノ メンセツ デ キク コト ヲ ノート ニ カキ ハジメタ",
  "一週間後、リヌは軍手をはめて、若い松のまわりの草を抜いていた。となりでは、高校生たちが、震災のあとに生まれた子どもたちに、松の植え方を教えている。佐々木さんが言った。「あの日を知らない子たちが、あの日を語る日が来るんです。」海風の中で、一本松は遠くに、変わらず立っていた。": "イチシュウカンゴ リヌ ハ グンテ ヲ ハメテ ワカイ マツ ノ マワリ ノ クサ ヲ ヌイテ イタ トナリ デ ハ コウコウセイタチ ガ シンサイ ノ アト ニ ウマレタ コドモタチ ニ マツ ノ ウエカタ ヲ オシエテ イル ササキサン ガ イッタ アノ ヒ ヲ シラナイ コタチ ガ アノ ヒ ヲ カタル ヒ ガ クル ンデス カイフウ ノ ナカ デ イッポンマツ ハ トオク ニ カワラズ タッテ イタ|イチシューカンゴ リヌ ワ グンテ ヲ ハメテ ワカイ マツ ノ マワリ ノ クサ ヲ ヌイテ イタ トナリ デ ワ コーコーセイタチ ガ シンサイ ノ アト ニ ウマレタ コドモタチ ニ マツ ノ ウエカタ ヲ オシエテ イル ササキサン ガ イッタ アノ ヒ ヲ シラナイ コタチ ガ アノ ヒ ヲ カタル ヒ ガ クル ンデス カイフー ノ ナカ デ イッポンマツ ワ トーク ニ カワラズ タッテ イタ",
