  "久保先生は、やさしく笑った。「五七五には、なっとらんし、季語もない。これは俳句やのうて、作文ですな。」先生は短冊を裏返した。「見たものを説明するんやなしに、一つだけ切り取るんです。例えば、城の上で何を感じました？」リヌは少し考えて、朝の湯けむりと、自分のひとりぼっちの影を思い出した。そして、新しい句を書いた。「湯けむりやペンギンひとり春の城。」": "クボ センセイ ハ ヤサシク ワラッタ ゴ ナナ ゴ ニ ハ ナッ トランシ キゴ モ ナイ コレ ハ ハイク ヤ ノ ウテ サクブンデス ナ センセイ ハ タンザク ヲ ウラガエシタ ミタ モノ ヲ セツメイ スル ン ヤ ナシ ニ ヒトツ ダケ キリトル ンデス タトエバ シロ ノ ウエ デ ナニ ヲ カンジマシタ リヌ ハ スコシ カンガエテ アサ ノ ユケムリ ト ジブン ノ ヒトリ ボッ チノ カゲ ヲ オモイダシタ ソシテ アタラシイ ク ヲ カイタ ユケムリ ヤ ペンギン ヒトリ ハル ノ シロ|クボ センセイ ワ ヤサシク ワラッタ ゴ ナナ ゴ ニ ワ ナッ トランシ キゴ モ ナイ コレ ワ ハイク ヤ ノ ウテ サクブンデス ナ センセイ ワ タンザク ヲ ウラガエシタ ミタ モノ ヲ セツメイ スル ン ヤ ナシ ニ ヒトツ ダケ キリトル ンデス タトエバ シロ ノ ウエ デ ナニ ヲ カンジマシタ リヌ ワ スコシ カンガエテ アサ ノ ユケムリ ト ジブン ノ ヒトリ ボッ チノ カゲ ヲ オモイダシタ ソシテ アタラシイ ク ヲ カイタ ユケムリ ヤ ペンギン ヒトリ ハル ノ シロ",
