  "佐々木さんはうなずいた。「ここには七万本の松原がありました。残ったのは、あの一本だけ。でも、根が海水にやられて、翌年には枯れてしまったんです。今立っているのは、幹を切って中に芯を通し、枝や葉を複製して元の姿に戻したものです。」佐々木さんは少し間をおいた。「一億五千万円もかけて残すことには、反対の声もありました。それでも、あれを見ると、生き残った者として、ここに立っていていいんだと思えるんです。」": "ササキサン ハ ウナズイタ ココ ニ ハ ナナ マンホン ノ マツバラ ガ アリマシタ ノコッタ ノ ハ アノ イッポン ダケ デモ ネ ガ カイスイ ニ ヤラレテ ヨクネン ニ ハ カレテ シマッタ ンデス イマ タッテ イル ノ ハ ミキ ヲ キッテ ナカ ニ シン ヲ トオシ エダ ヤ ハ ヲ フクセイ シテ モト ノ スガタ ニ モドシタ モノデス ササキサン ハ スコシ マ ヲ オイタ イチ オク ゴ セン マンエン モ カケテ ノコス コト ニ ハ ハンタイ ノ コエ モ アリマシタ ソレデモ アレ ヲ ミルト イキノコッタ モノ トシテ ココ ニ タッテ イテ イイ ンダ ト オモエル ンデス|ササキサン ワ ウナズイタ ココ ニ ワ ナナ マンホン ノ マツバラ ガ アリマシタ ノコッタ ノ ワ アノ イッポン ダケ デモ ネ ガ カイスイ ニ ヤラレテ ヨクネン ニ ワ カレテ シマッタ ンデス イマ タッテ イル ノ ワ ミキ ヲ キッテ ナカ ニ シン ヲ トーシ エダ ヤ ハ ヲ フクセイ シテ モト ノ スガタ ニ モドシタ モノデス ササキサン ワ スコシ マ ヲ オイタ イチ オク ゴ セン マンエン モ カケテ ノコス コト ニ ワ ハンタイ ノ コエ モ アリマシタ ソレデモ アレ ヲ ミルト イキノコッタ モノ トシテ ココ ニ タッテ イテ イイ ンダ ト オモエル ンデス",
