  "三千円以上買うと送料が無料になります。": "サンゼンエン イジョウ カウト ソウリョウ ガ ムリョウ ニ ナリマス|サンゼンエン イジョー カウト ソーリョー ガ ムリョー ニ ナリマス",
  "三層の木造の建物の屋根の上で、白鷺の飾りが朝日を受けていた。道後温泉本館だ。「漱石も、ここの湯に通ったんですよ。『坊っちゃん』の主人公は、湯船で泳いで、次の日に『湯の中で泳ぐべからず』という札を見つけて、腹を立てるでしょう。」久保先生は愉快そうに笑った。「その漱石の親友が、この町で生まれた正岡子規です。」": "サンソウ ノ モクゾウ ノ タテモノ ノ ヤネ ノ ウエ デ シラサギ ノ カザリ ガ アサヒ ヲ ウケテ イタ ドウゴ オンセン ホンカンダ ソウセキ モ ココ ノ ユ ニ トオッタ ンデス ヨ ボッチャン ノ シュジンコウ ハ ユブネ デ オヨイデ ツギ ノ ヒ ニ ユ ノ ナカ デ オヨグベカラズ トイウ フダ ヲ ミツケテ ハラ ヲ タテルデショウ クボ センセイ ハ ユカイソウ ニ ワラッタ ソノ ソウセキ ノ シンユウ ガ コノ マチ デ ウマレタ マサオカ シキデス|サンソー ノ モクゾー ノ タテモノ ノ ヤネ ノ ウエ デ シラサギ ノ カザリ ガ アサヒ ヲ ウケテ イタ ドーゴ オンセン ホンカンダ ソーセキ モ ココ ノ ユ ニ トーッタ ンデス ヨ ボッチャン ノ シュジンコー ワ ユブネ デ オヨイデ ツギ ノ ヒ ニ ユ ノ ナカ デ オヨグベカラズ トユウ フダ ヲ ミツケテ ハラ ヲ タテルデショウ クボ センセイ ワ ユカイソー ニ ワラッタ ソノ ソーセキ ノ シンユー ガ コノ マチ デ ウマレタ マサオカ シキデス",
  "三足": "サンソク",
  "三段目からでも、村はよく見えた。田んぼの間に、同じ向きの三角の屋根がいくつも並び、その向こうに雪の残る山がそびえている。夕方、最後の茅が刈りそろえられると、屋根は夕日に金色に光った。棟梁が大きな声で言った。「皆様のおかげで、無事に葺き終わりました。本当にお疲れさまでした！」拍手の中で、翔がリヌの肩をたたいた。「このあと、みんなで打ち上げやけど、来るやろ？」": "サンダンメ カラ デモ ムラ ハ ヨク ミエタ タンボ ノ マ ニ オナジ ムキ ノ サンカク ノ ヤネ ガ イクツ モ ナラビ ソノ ムコウ ニ ユキ ノ ノコル ヤマ ガ ソビエテ イル ユウガタ サイゴ ノ カヤ ガ カリ ソロエラレルト ヤネ ハ ユウヒ ニ キンイロ ニ ヒカッタ トウリョウ ガ オオキナ コエ デ イッタ ミナサマ ノ オカゲ デ ブジ ニ フキ オワリマシタ ホントウニ オツカレサマデシタ ハクシュ ノ ナカ デ ショウ ガ リヌ ノ カタ ヲ タタイタ コノ アト ミンナ デ ウチアゲヤケド クルヤロ|サンダンメ カラ デモ ムラ ワ ヨク ミエタ タンボ ノ マ ニ オナジ ムキ ノ サンカク ノ ヤネ ガ イクツ モ ナラビ ソノ ムコー ニ ユキ ノ ノコル ヤマ ガ ソビエテ イル ユーガタ サイゴ ノ カヤ ガ カリ ソロエラレルト ヤネ ワ ユーヒ ニ キンイロ ニ ヒカッタ トーリョー ガ オーキナ コエ デ イッタ ミナサマ ノ オカゲ デ ブジ ニ フキ オワリマシタ ホントーニ オツカレサマデシタ ハクシュ ノ ナカ デ ショー ガ リヌ ノ カタ ヲ タタイタ コノ アト ミンナ デ ウチアゲヤケド クルヤロ",
