  "似ています": "ニテ イマス",
  "慈海さんは、にっこりほほえんだ。「ございますよ。実は、お寺ではお酒のことを『般若湯』と申すこともございます。『知恵のお湯』という意味でございます。」リヌが笑うと、慈海さんも小さく笑った。「ただ、明朝のお勤めに起きられる程度に、お楽しみくださいませ。」": "ジカイサン ハ ニッコリ ホホエンダ ゴザイマス ヨ ジツハ オテラ デ ハ オサケ ノ コト ヲ ハンニャトウ ト モウス コト モゴザイマス チエ ノ オユ トイウ イミデゴザイマス リヌ ガ ワラウト ジカイサン モ チイサク ワラッタ タダ ミンチョウ ノ オツトメ ニ オキラレル テイド ニ オタノシミ クダサイマセ|ジカイサン ワ ニッコリ ホホエンダ ゴザイマス ヨ ジツワ オテラ デ ワ オサケ ノ コト ヲ ハンニャトー ト モース コト モゴザイマス チエ ノ オユ トユウ イミデゴザイマス リヌ ガ ワラウト ジカイサン モ チーサク ワラッタ タダ ミンチョー ノ オツトメ ニ オキラレル テイド ニ オタノシミ クダサイマセ",
  "慈海さんはうれしそうに答えた。「胡麻をすり鉢で、一時間ほどすり続けます。それを葛と水と合わせて、弱い火でゆっくり練るのです。すり続けるのも、修行の一つでございます。」リヌは、なめらかな胡麻豆腐をもう一口食べた。一時間分の静かな時間の味がした。": "ジカイサン ハ ウレシソウ ニ コタエタ ゴマ ヲ スリバチ デ イチジカン ホド スリ ツヅケマス ソレ ヲ カズラ ト ミズ ト アワセテ ヨワイ ヒ デ ユックリ ネル ノデス スリ ツヅケル ノ モ シュギョウ ノ ヒトツデゴザイマス リヌ ハ ナメラカナ ゴマ トウフ ヲ モウ イチクチ タベタ イチジカンブン ノ シズカナ ジカン ノ アジ ガ シタ|ジカイサン ワ ウレシソー ニ コタエタ ゴマ ヲ スリバチ デ イチジカン ホド スリ ツズケマス ソレ ヲ カズラ ト ミズ ト アワセテ ヨワイ ヒ デ ユックリ ネル ノデス スリ ツズケル ノ モ シュギョー ノ ヒトツデゴザイマス リヌ ワ ナメラカナ ゴマ トーフ ヲ モー イチクチ タベタ イチジカンブン ノ シズカナ ジカン ノ アジ ガ シタ",
