  "次に来たのは、ヒョウ柄の服を着た常連のおばちゃんだった。「兄ちゃん、新顔やな。これ、なんぼ？」「六百円です。」「高いなあ。ちょっとまけてえな。」おじいちゃんは何も言わずに、にやにやしながらリヌを見ている。": "ツギニ キタ ノ ハ ヒョウガラ ノ フク ヲ キタ ジョウレン ノ オバチャンダッタ ニイチャン シンガオヤ ナ コレ ナンボ ロッピャクエンデス タカイ ナア チョット マケテ エ ナ オジイチャン ハ ナニ モ イワズ ニ ニヤニヤ シナガラ リヌ ヲ ミテ イル|ツギニ キタ ノ ワ ヒョーガラ ノ フク ヲ キタ ジョーレン ノ オバチャンダッタ ニーチャン シンガオヤ ナ コレ ナンボ ロッピャクエンデス タカイ ナー チョット マケテ エ ナ オジーチャン ワ ナニ モ イワズ ニ ニヤニヤ シナガラ リヌ ヲ ミテ イル",
  "次のサービスエリアで休憩しましょう。": "ツギ ノ サービス エリア デ キュウケイ シマショウ|ツギ ノ サービス エリア デ キューケイ シマショウ",
