  "次の場面では、それを見ていたぼんやりした男が、まねをしようとする。ところが、次の晩、待ちきれずに早い時間に出かけてしまった。まずいそばを我慢して食べ、同じように数え始める。「ひい、ふう、みい、よう、いつ、むう、なな、やあ……今、何どきだい？」「へい、四つで。」「五つ、六つ、七つ、八つ……。」客席は、さっきよりも大きな笑いに包まれた。": "ツギ ノ バメン デ ハ ソレ ヲ ミテ イタ ボンヤリ シタ オトコ ガ マネ ヲ シヨウ ト スル トコロガ ツギ ノ バン マチ キレズ ニ ハヤイ ジカン ニ デカケテ シマッタ マズイ ソバ ヲ ガマン シテ タベ オナジ ヨウ ニ カゾエ ハジメル ヒ イ フウ ミイ ヨウ イツ ムウ ナ ナ ヤア イマ ナニ ドキ ダイ ヘ イ ヨッツ デ イツツ ムッツ ナナツ ヤッツ キャクセキ ハ サッキ ヨリ モ オオキナ ワライ ニ ツツマレタ|ツギ ノ バメン デ ワ ソレ ヲ ミテ イタ ボンヤリ シタ オトコ ガ マネ ヲ シヨウ ト スル トコロガ ツギ ノ バン マチ キレズ ニ ハヤイ ジカン ニ デカケテ シマッタ マズイ ソバ ヲ ガマン シテ タベ オナジ ヨー ニ カゾエ ハジメル ヒ イ フー ミイ ヨー イツ ムウ ナ ナ ヤー イマ ナニ ドキ ダイ エ イ ヨッツ デ イツツ ムッツ ナナツ ヤッツ キャクセキ ワ サッキ ヨリ モ オーキナ ワライ ニ ツツマレタ",
  "次の朝、リヌが下りていくと、八重さんはもう竹ぼうきを手に、家の前を掃いていた。「おはようさん。昨日は、ようわかってくれはりましたなあ。」八重さんは、ほうきをリヌに渡した。「門掃き、してみはる？ただな、お隣の前は、ちょっとだけにしとくんどすえ。全部掃いたら、お隣さんが掃除してへんみたいに見えて、かえって失礼になりますさかい。」": "ツギ ノ アサ リヌ ガ オリテ イクト ヤエサン ハ モウ タケ ボウキ ヲ テ ニ イエ ノ マエ ヲ ハイテ イタ オハヨウサン キノウ ハ ヨウ ワカッテ クレ ハリマシタ ナア ヤエサン ハ ホウキ ヲ リヌ ニ ワタシタ モン ハキ シテ ミハル タダ ナ オトナリ ノ マエ ハ チョット ダケ ニ シ トク ンドス エ ゼンブ ハイタラ オトナリサン ガ ソウジ シテ ヘン ミタイ ニ ミエテ カエッテ シツレイ ニ ナリマスサカイ|ツギ ノ アサ リヌ ガ オリテ イクト ヤエサン ワ モー タケ ボウキ ヲ テ ニ イエ ノ マエ ヲ ハイテ イタ オハヨーサン キノー ワ ヨー ワカッテ クレ ハリマシタ ナー ヤエサン ワ ホーキ ヲ リヌ ニ ワタシタ モン ハキ シテ ミハル タダ ナ オトナリ ノ マエ ワ チョット ダケ ニ シ トク ンドス エ ゼンブ ハイタラ オトナリサン ガ ソージ シテ ヘン ミタイ ニ ミエテ カエッテ シツレイ ニ ナリマスサカイ",
  "次の朝、リヌは村の人たちといっしょに雪かきをした。ペンギンの足は雪に強い。「助かったよ！」とみんなが笑った。リヌは、自分も少しだけ「結」の仲間になれた気がした。": "ツギ ノ アサ リヌ ハ ムラ ノ ヒトタチ ト イッショ ニ ユキカキ ヲ シタ ペンギン ノ アシ ハ ユキ ニ ツヨイ タスカッタ ヨ ト ミンナ ガ ワラッタ リヌ ハ ジブン モ スコシ ダケ ユイ ノ ナカマ ニ ナレタ キ ガ シタ|ツギ ノ アサ リヌ ワ ムラ ノ ヒトタチ ト イッショ ニ ユキカキ ヲ シタ ペンギン ノ アシ ワ ユキ ニ ツヨイ タスカッタ ヨ ト ミンナ ガ ワラッタ リヌ ワ ジブン モ スコシ ダケ ユイ ノ ナカマ ニ ナレタ キ ガ シタ",
