  "神戸の北野の坂を上りながら、ジュリアは一枚の古い写真をリヌに見せた。ジュリアはパラナ州ロンドリーナ出身の日系四世で、今は神戸の大学に留学している。「これ、ひいおじいちゃん。十八歳のとき、この坂の上の建物から、ブラジルへの船に乗ったんだって。」坂の上に、薄い茶色の古い建物が見えてきた。": "コウベ ノ キタノ ノ サカ ヲ ノボリナガラ ジュリア ハ イチマイ ノ フルイ シャシン ヲ リヌ ニ ミセタ ジュリア ハ パラナシュウ ロンドリーナ シュッシン ノ ニッケイ ヨンセイデ イマ ハ コウベ ノ ダイガク ニ リュウガク シテ イル コレ ヒイ オジイチャン ジュウハッサイ ノ トキ コノ サカ ノ ウエ ノ タテモノ カラ ブラジル ヘ ノ フネ ニ ノッタ ンダ ッテ サカ ノ ウエ ニ ウスイ チャイロ ノ フルイ タテモノ ガ ミエテ キタ|コーベ ノ キタノ ノ サカ ヲ ノボリナガラ ジュリア ワ イチマイ ノ フルイ シャシン ヲ リヌ ニ ミセタ ジュリア ワ パラナシュー ロンドリーナ シュッシン ノ ニッケイ ヨンセイデ イマ ワ コーベ ノ ダイガク ニ リューガク シテ イル コレ ヒイ オジーチャン ジュウハッサイ ノ トキ コノ サカ ノ ウエ ノ タテモノ カラ ブラジル エ ノ フネ ニ ノッタ ンダ ッテ サカ ノ ウエ ニ ウスイ チャイロ ノ フルイ タテモノ ガ ミエテ キタ",
