  "天守の上から、松山の町と、その向こうに瀬戸内の島々が見渡せた。江戸時代から残る、数少ない本物の天守の一つだ。久保先生は、胸を張って詠んだ。「春や昔十五万石の城下哉。」「『や』と『哉』が切れ字です。『や』で一度、息を切る。春だなあ、と。そして昔、十五万石の大名がいた城下町を、最後に『哉』で、しみじみと包みこむ。故郷を離れた子規の、なつかしさと誇りが、この二つの字に詰まっとるんです。」": "テンシュ ノ ウエ カラ マツヤマ ノ マチ ト ソノ ムコウ ニ セトウチ ノ シマジマ ガ ミワタセタ エド ジダイ カラ ノコル カズスクナイ ホンモノ ノ テンシュ ノ ヒトツダ クボ センセイ ハ ムネ ヲ ハッテ ヨンダ ハル ヤ ムカシ ジュウ ゴ マンセキ ノ ジョウカ カナ ヤ ト カナ ガ キレジデス ヤ デ イチド イキ ヲ キル ハルダ ナア ト ソシテ ムカシ ジュウ ゴ マンセキ ノ ダイミョウ ガ イタ ジョウカマチ ヲ サイゴ ニ カナ デ シミジミ ト ツツミ コム コキョウ ヲ ハナレタ シキ ノ ナツカシサ ト ホコリ ガ コノ フタツ ノ ジ ニ ツマッ トル ンデス|テンシュ ノ ウエ カラ マツヤマ ノ マチ ト ソノ ムコー ニ セトウチ ノ シマジマ ガ ミワタセタ エド ジダイ カラ ノコル カズスクナイ ホンモノ ノ テンシュ ノ ヒトツダ クボ センセイ ワ ムネ ヲ ハッテ ヨンダ ハル ヤ ムカシ ジュー ゴ マンセキ ノ ジョーカ カナ ヤ ト カナ ガ キレジデス ヤ デ イチド イキ ヲ キル ハルダ ナー ト ソシテ ムカシ ジュー ゴ マンセキ ノ ダイミョー ガ イタ ジョーカマチ ヲ サイゴ ニ カナ デ シミジミ ト ツツミ コム コキョー ヲ ハナレタ シキ ノ ナツカシサ ト ホコリ ガ コノ フタツ ノ ジ ニ ツマッ トル ンデス",
