  "二人は一丁目から七丁目まで、二キロ半あまりのアーケードを歩いた。天満宮にお参りして、古い本屋や八百屋をのぞき、コロッケを食べ歩いた。どの店でも、陽菜が「この子、今日うちで働いてくれてん」と紹介すると、「まいど！」と声がかかった。リヌは帰り道、小さな声で練習した。「おおきに。」": "フタリ ハ イチチョウメ カラ ナナチョウメ マデ ニキロ ハンアマリ ノ アーケード ヲ アルイタ テンマングウ ニ オマイリ シテ フルイ ホンヤ ヤ ヤオヤ ヲ ノゾキ コロッケ ヲ タベ アルイタ ドノ ミセ デ モ ヒ サイ ガ コノ コ キョウ ウチ デ ハタライテ クレ テン ト ショウカイ スルト マイド ト コエ ガ カカッタ リヌ ハ カエリミチ チイサナ コエ デ レンシュウ シタ オオキニ|フタリ ワ イチチョーメ カラ ナナチョーメ マデ ニキロ ハンアマリ ノ アーケード ヲ アルイタ テンマングー ニ オマイリ シテ フルイ ホンヤ ヤ ヤオヤ ヲ ノゾキ コロッケ ヲ タベ アルイタ ドノ ミセ デ モ ヒ サイ ガ コノ コ キョー ウチ デ ハタライテ クレ テン ト ショーカイ スルト マイド ト コエ ガ カカッタ リヌ ワ カエリミチ チーサナ コエ デ レンシュー シタ オーキニ",
