  "二人は新宿の古いそば屋に入った。リヌはかけそばを前に、師匠のまねをして、ずずーっと音を立ててすすった。となりの席のおじさんが笑った。「ペンギンさん、いい音だねえ。落語帰りかい？」リヌは胸を張って答えた。「はい、時そばを聞いてきました。今、何どきですか。」三人は声をそろえて笑った。": "フタリ ハ シンジュク ノ フルイ ソバヤ ニ ハイッタ リヌ ハ カケ ソバ ヲ マエ ニ シショウ ノ マネ ヲ シテ ズ ズーット オト ヲ タテテ ススッタ トナリ ノ セキ ノ オジサン ガ ワラッタ ペンギンサン イイ オトダ ネエ ラクゴガエリ カイ リヌ ハ ムネ ヲ ハッテ コタエタ ハイ トキ ソバ ヲ キイテ キマシタ イマ ナニ ドキデス カ サンニン ハ コエ ヲ ソロエテ ワラッタ|フタリ ワ シンジュク ノ フルイ ソバヤ ニ ハイッタ リヌ ワ カケ ソバ ヲ マエ ニ シショー ノ マネ ヲ シテ ズ ズーット オト ヲ タテテ ススッタ トナリ ノ セキ ノ オジサン ガ ワラッタ ペンギンサン イイ オトダ ネー ラクゴガエリ カイ リヌ ワ ムネ ヲ ハッテ コタエタ ハイ トキ ソバ ヲ キイテ キマシタ イマ ナニ ドキデス カ サンニン ワ コエ ヲ ソロエテ ワラッタ",
