  "二人は像の前で写真を一枚撮って、駅へ向かった。ジュリアは電車の中で、ずっと窓の外を見ていた。家に帰ってから、リヌは岡本さんのメモを見直して、鹿児島の町の名前を地図で探した。今度会ったら、ジュリアにもっと話を聞いてみようと思った。": "フタリ ハ ゾウ ノ マエ デ シャシン ヲ イチマイ トッテ エキ ヘ ムカッタ ジュリア ハ デンシャ ノ ナカ デ ズット マド ノ ソト ヲ ミテ イタ イエ ニ カエッテ カラ リヌ ハ オカモトサン ノ メモ ヲ ミナオシテ カゴシマ ノ マチ ノ ナマエ ヲ チズ デ サガシタ コンド アッタラ ジュリア ニ モット ハナシ ヲ キイテ ミヨウ ト オモッタ|フタリ ワ ゾー ノ マエ デ シャシン ヲ イチマイ トッテ エキ エ ムカッタ ジュリア ワ デンシャ ノ ナカ デ ズット マド ノ ソト ヲ ミテ イタ イエ ニ カエッテ カラ リヌ ワ オカモトサン ノ メモ ヲ ミナオシテ カゴシマ ノ マチ ノ ナマエ ヲ チズ デ サガシタ コンド アッタラ ジュリア ニ モット ハナシ ヲ キイテ ミヨウ ト オモッタ",
  "二人は速いペースで登り始めたが、七合目あたりで大輝の顔色が悪くなった。「なんか、頭がガンガンする……。」リヌも息が苦しい。岩に座って水を飲んでいると、下りてきた山岳ガイドが声をかけてくれた。「急いで登ると、体が高さに慣れないんですよ。水をこまめに飲んで、ゆっくり、深く息をしてください。」": "フタリ ハ ハヤイ ペース デ ノボリ ハジメタガ ナナゴウメアタリ デ ダイテル ノ カオイロ ガ ワルク ナッタ ナン カ アタマ ガ ガンガン スル リヌ モ イキ ガ クルシイ イワ ニ スワッテ ミズ ヲ ノンデ イルト オリテ キタ サンガク ガイド ガ コエ ヲ カケテ クレタ イソイデ ノボルト カラダ ガ タカサ ニ ナレナイ ンデス ヨ ミズ ヲ コマメ ニ ノンデ ユックリ フカク イキ ヲ シテ クダサイ|フタリ ワ ハヤイ ペース デ ノボリ ハジメタガ ナナゴーメアタリ デ ダイテル ノ カオイロ ガ ワルク ナッタ ナン カ アタマ ガ ガンガン スル リヌ モ イキ ガ クルシイ イワ ニ スワッテ ミズ ヲ ノンデ イルト オリテ キタ サンガク ガイド ガ コエ ヲ カケテ クレタ イソイデ ノボルト カラダ ガ タカサ ニ ナレナイ ンデス ヨ ミズ ヲ コマメ ニ ノンデ ユックリ フカク イキ ヲ シテ クダサイ",
  "二人は大きな火口のまわりを、一時間半かけて歩いた。途中の山頂郵便局から、リヌは南極の家族にはがきを出した。そして、標高三千七百七十六メートルの最高地点、剣ヶ峰に着くと、「日本最高峰」と刻まれた石の前で写真を撮った。足もとの火口は深く、静かだった。": "フタリ ハ オオキナ カコウ ノ マワリ ヲ イチジカン ハン カケテ アルイタ トチュウ ノ サンチョウ ユウビンキョク カラ リヌ ハ ナンキョク ノ カゾク ニ ハガキ ヲ ダシタ ソシテ ヒョウコウ サンゼン ナナ ヒャク ナナ ジュウ ロクメートル ノ サイコウ チテン ケンガミネ ニ ツクト ニホン サイコウホウ ト キザマレタ イシ ノ マエ デ シャシン ヲ トッタ アシモト ノ カコウ ハ フカク シズカダッタ|フタリ ワ オーキナ カコー ノ マワリ ヲ イチジカン ハン カケテ アルイタ トチュー ノ サンチョー ユービンキョク カラ リヌ ワ ナンキョク ノ カゾク ニ ハガキ ヲ ダシタ ソシテ ヒョーコー サンゼン ナナ ヒャク ナナ ジュー ロクメートル ノ サイコー チテン ケンガミネ ニ ツクト ニホン サイコーホー ト キザマレタ イシ ノ マエ デ シャシン ヲ トッタ アシモト ノ カコー ワ フカク シズカダッタ",
  "二人は津波伝承館に入った。ガラスケースの中には、泥にまみれた看板や、二時四十六分をさしたまま止まった時計が並んでいる。壁の映像では、水門を閉めに向かって帰らなかった消防団員たちのことが紹介されていた。出口の近くには、訪れた人がメッセージを書き残すノートが置いてある。ページには、さまざまな言葉と文字が重なっていた。": "フタリ ハ ツナミ デンショウカン ニ ハイッタ ガラスケース ノ ナカ ニ ハ ドロ ニ マミレタ カンバン ヤ ニジ ヨン ジュウ ロクフン ヲ サシタ ママ トマッタ トケイ ガ ナランデ イル カベ ノ エイゾウ デ ハ スイモン ヲ シメ ニ ムカッテ カエラナカッタ ショウボウダンインタチ ノ コト ガ ショウカイ サレテ イタ デグチ ノ チカク ニ ハ オトズレタ ヒト ガ メッセージ ヲ カキノコス ノート ガ オイテ アル ページ ニ ハ サマザマナ コトバ ト モジ ガ カサナッテ イタ|フタリ ワ ツナミ デンショーカン ニ ハイッタ ガラスケース ノ ナカ ニ ワ ドロ ニ マミレタ カンバン ヤ ニジ ヨン ジュー ロクフン ヲ サシタ ママ トマッタ トケイ ガ ナランデ イル カベ ノ エイゾー デ ワ スイモン ヲ シメ ニ ムカッテ カエラナカッタ ショーボーダンインタチ ノ コト ガ ショーカイ サレテ イタ デグチ ノ チカク ニ ワ オトズレタ ヒト ガ メッセージ ヲ カキノコス ノート ガ オイテ アル ページ ニ ワ サマザマナ コトバ ト モジ ガ カサナッテ イタ",
  "二人は道のわきの岩に腰を下ろした。やがて雲の海の向こうから、真っ赤な太陽が顔を出した。まわりの登山客から、自然に拍手が起こる。頂上には行けなかったけれど、大輝の頭痛はだんだん治まってきた。「次は、頂上で見ような。」二人は約束して、ゆっくり山を下りた。": "フタリ ハ ミチ ノ ワキ ノ イワ ニ コシ ヲ オロシタ ヤガテ クモ ノ ウミ ノ ムコウ カラ マッカナ タイヨウ ガ カオ ヲ ダシタ マワリ ノ トザン キャク カラ シゼン ニ ハクシュ ガ オコル チョウジョウ ニ ハ イケナカッタケレド ダイテル ノ ズツウ ハ ダンダン オサマッテ キタ ツギ ハ チョウジョウ デ ミヨウ ナ フタリ ハ ヤクソク シテ ユックリ ヤマ ヲ オリタ|フタリ ワ ミチ ノ ワキ ノ イワ ニ コシ ヲ オロシタ ヤガテ クモ ノ ウミ ノ ムコー カラ マッカナ タイヨー ガ カオ ヲ ダシタ マワリ ノ トザン キャク カラ シゼン ニ ハクシュ ガ オコル チョージョー ニ ワ イケナカッタケレド ダイテル ノ ズツー ワ ダンダン オサマッテ キタ ツギ ワ チョージョー デ ミヨウ ナ フタリ ワ ヤクソク シテ ユックリ ヤマ ヲ オリタ",
