  "八重さんの箸が止まった。「毎年、何百軒もの町家が壊されて、マンションや駐車場になってますのや。直すのにお金はかかるし、冬は底冷えするし、若い人が住みとうないのも無理ないわ。」八重さんは坪庭に目をやった。「東京の息子は、売ったらええ、言いますけどな。この庭に雪が積もるのを見ると、どうしても決められしませんのや。」": "ヤエサン ノ ハシ ガ トマッタ マイトシ ナン ヒャクケン モ ノ マチヤ ガ コワサレテ マンション ヤ チュウシャジョウ ニ ナッテマス ノヤ ナオス ノ ニ オカネ ハ カカルシ フユ ハ ソコビエ スルシ ワカイ ヒト ガ スミトウナイ ノ モ ムリ ナイ ワ ヤエサン ハ ツボ ニワ ニ メ ヲ ヤッタ トウキョウ ノ ムスコ ハ ウッタラ エエ イイマスケド ナ コノ ニワ ニ ユキ ガ ツモル ノ ヲ ミルト ドウシテモ キメラレ シマセン ノヤ|ヤエサン ノ ハシ ガ トマッタ マイトシ ナン ヒャクケン モ ノ マチヤ ガ コワサレテ マンション ヤ チューシャジョー ニ ナッテマス ノヤ ナオス ノ ニ オカネ ワ カカルシ フユ ワ ソコビエ スルシ ワカイ ヒト ガ スミトーナイ ノ モ ムリ ナイ ワ ヤエサン ワ ツボ ニワ ニ メ ヲ ヤッタ トーキョー ノ ムスコ ワ ウッタラ エエ イイマスケド ナ コノ ニワ ニ ユキ ガ ツモル ノ ヲ ミルト ドーシテモ キメラレ シマセン ノヤ",
  "八重さんは一瞬だまってから、にっこり笑った。「ほな、ぶぶ漬けでも、どうどす？」「わあ、いただきます！」リヌはお茶漬けをおいしく二杯食べて、十一時すぎに二階へ上がった。次の朝、八重さんはいつもどおりていねいだったが、どこか少しだけ、よそよそしかった。": "ヤエサン ハ イッシュン ダマッテ カラ ニッコリ ワラッタ ホナ ブ ブ ツケ デ モ ドウ ドス ワア イタダキマス リヌ ハ オチャヅケ ヲ オイシク ニハイ タベテ ジュウ イチジスギ ニ ニカイ ヘ アガッタ ツギ ノ アサ ヤエサン ハ イツモ ドオリ テイネイダッタガ ドコ カ スコシ ダケ ヨソヨソシカッタ|ヤエサン ワ イッシュン ダマッテ カラ ニッコリ ワラッタ ホナ ブ ブ ツケ デ モ ドー ドス ワア イタダキマス リヌ ワ オチャズケ ヲ オイシク ニハイ タベテ ジュー イチジスギ ニ ニカイ エ アガッタ ツギ ノ アサ ヤエサン ワ イツモ ドーリ テイネイダッタガ ドコ カ スコシ ダケ ヨソヨソシカッタ",
