  "夕ご飯のあと、なつきが言った。「さあ、今夜は徹夜おどりだよ。朝までおどるんだ。」おばあちゃんが、リヌにゆかたを着せてくれた。「げたで、カランコロンと音を鳴らしておどるのが、郡上のおどり方だからね。」": "ユウ ゴハン ノ アト ナツキ ガ イッタ サア コンヤ ハ テツヤ オドリダ ヨ アサ マデ オドル ンダ オバアチャン ガ リヌ ニ ユカタ ヲ キセテ クレタ ゲタ デ カラン コロン ト オト ヲ ナラシテ オドル ノ ガ グジョウ ノ オドリカタダカラ ネ|ユー ゴハン ノ アト ナツキ ガ イッタ サー コンヤ ワ テツヤ オドリダ ヨ アサ マデ オドル ンダ オバーチャン ガ リヌ ニ ユカタ ヲ キセテ クレタ ゲタ デ カラン コロン ト オト ヲ ナラシテ オドル ノ ガ グジョー ノ オドリカタダカラ ネ",
