  "夕食に、八重さんはおばんざいを並べてくれた。万願寺とうがらしの炊いたん、湯葉、にしんなす。食べながら、八重さんはいたずらっぽく聞いた。「ぶぶ漬けの話、知ってはります？『ぶぶ漬けでもどうどす』言われたら、『そろそろお帰り』いう意味や、いうの。」八重さんはくすくす笑った。「あれは半分冗談どす。けど、はっきり言わんと、相手に察してもらう。狭い町で、長いこと仲良う暮らすための知恵やったんどすわ。」": "ユウショク ニ ヤエサン ハ オバン ザイヲ ナラベテ クレタ マンガンジトウガラシ ノ タイタ ン ユバ ニシン ナス タベナガラ ヤエサン ハ イタズラッポク キイタ ブ ブ ツケ ノ ハナシ シッテ ハリマス ブ ブ ツケ デ モ ドウドス イワレタラ ソロソロ オカエリ イウ イミ ヤ イウ ノ ヤエサン ハ クスクス ワラッタ アレ ハ ハンブン ジョウダンドス ケド ハッキリ イワント アイテ ニ サッシテ モラウ セマイ マチ デ ナガイ コト ナカヨウ クラス タメ ノ チエ ヤッタ ンドス ワ|ユーショク ニ ヤエサン ワ オバン ザイヲ ナラベテ クレタ マンガンジトーガラシ ノ タイタ ン ユバ ニシン ナス タベナガラ ヤエサン ワ イタズラッポク キイタ ブ ブ ツケ ノ ハナシ シッテ ハリマス ブ ブ ツケ デ モ ドードス イワレタラ ソロソロ オカエリ イウ イミ ヤ イウ ノ ヤエサン ワ クスクス ワラッタ アレ ワ ハンブン ジョーダンドス ケド ハッキリ イワント アイテ ニ サッシテ モラウ セマイ マチ デ ナガイ コト ナカヨー クラス タメ ノ チエ ヤッタ ンドス ワ",
