  "和子さんは、お茶を一口飲んでから答えた。「世界遺産になってから、店もできて、村はにぎやかになったよ。それはありがたい。けど、よその家の庭に黙って入って、写真を撮る人もおる。」和子さんは、茅の屋根を見上げた。「ここは博物館やなくて、人が暮らしとる村なんやさ。それだけは、わかってほしいなあ。」": "カズコサン ハ オチャ ヲ イチクチ ノンデ カラ コタエタ セカイ イサン ニ ナッテ カラ ミセ モ デキテ ムラ ハ ニギヤカ ニ ナッタ ヨ ソレ ハ アリガタイ ケド ヨソ ノ イエ ノ ニワ ニ ダマッテ ハイッテ シャシン ヲ トル ヒト モ オル カズコサン ハ カヤ ノ ヤネ ヲ ミアゲタ ココ ハ ハクブツカン ヤ ナクテ ヒト ガ クラシ トル ムラナ ンヤ サ ソレ ダケ ハ ワカッテ ホシイ ナア|カズコサン ワ オチャ ヲ イチクチ ノンデ カラ コタエタ セカイ イサン ニ ナッテ カラ ミセ モ デキテ ムラ ワ ニギヤカ ニ ナッタ ヨ ソレ ワ アリガタイ ケド ヨソ ノ イエ ノ ニワ ニ ダマッテ ハイッテ シャシン ヲ トル ヒト モ オル カズコサン ワ カヤ ノ ヤネ ヲ ミアゲタ ココ ワ ハクブツカン ヤ ナクテ ヒト ガ クラシ トル ムラナ ンヤ サ ソレ ダケ ワ ワカッテ ホシイ ナー",
  "話がはずみ、気がつくと柱時計は九時半を回っていた。八重さんはちらりと時計を見てから、リヌの手首に目をやり、にっこりほほえんだ。「まあ、リヌさん、ええ時計してはりますなあ。」": "ハナシ ガ ハズミ キ ガ ツクト ハシラドケイ ハ キュウジハン ヲ マワッテ イタ ヤエサン ハ チラリト トケイ ヲ ミテ カラ リヌ ノ テクビ ニ メ ヲ ヤリ ニッコリ ホホエンダ マア リヌサン エ エ トケイ シテ ハリマス ナア|ハナシ ガ ハズミ キ ガ ツクト ハシラドケイ ワ キュージハン ヲ マワッテ イタ ヤエサン ワ チラリト トケイ ヲ ミテ カラ リヌ ノ テクビ ニ メ ヲ ヤリ ニッコリ ホホエンダ マー リヌサン エ エ トケイ シテ ハリマス ナー",
